namespace ror_fuzz {
void Init()
{
    static bool done = false;
    if (done) return;
    done = true;
    // The CVars the parsers and Console read (all default false, as in a fresh RoR.cfg).
    RoR::App::diag_log_console_echo    = new RoR::CVar("diag_log_console_echo", "", RoR::CVAR_TYPE_BOOL);
    RoR::App::diag_rig_log_node_import = new RoR::CVar("diag_rig_log_node_import", "", RoR::CVAR_TYPE_BOOL);
    RoR::App::diag_rig_log_node_stats  = new RoR::CVar("diag_rig_log_node_stats", "", RoR::CVAR_TYPE_BOOL);
    // OGRE's logging singleton; no file, no stdout (suppressFileOutput, !debuggerOutput).
    Ogre::LogManager* lm = new Ogre::LogManager();
    lm->createLog("fuzz.log", true, false, true);
    lm->setLogDetail(Ogre::LL_LOW);
}

void Reset()
{
    // Console keeps every message it was given; drop them so inputs stay independent.
    // All parser messages are posted with net user id 0.
    RoR::App::GetConsole()->purgeNetChatMessagesByUser(0);
}
} // namespace ror_fuzz
